#!/usr/bin/env python
"""Write docs/ml/model-card.md from the latest registry version per group (exact numbers, no rounding beyond 4 dp)."""
import sys

from atlas.ml import registry as R


def f(v, d=4):
    return "—" if v is None else (f"{v:.{d}f}" if isinstance(v, float) else str(v))


def main(out="docs/ml/model-card.md"):
    latest = {}
    for m in R.list_models():
        latest.setdefault(m["group"], m)
    L = ["# Model card: ATLAS meta-labeler (latest per group)", "",
         "Generated by `scripts/ml_model_card.py` from `var/ml/registry`. Purged walk-forward OOS, after costs. "
         "Primary variant `hgb_conformal` was pre-declared before training.", ""]
    for g in sorted(latest):
        m = latest[g]
        mt = m["metrics"]
        L += [f"## {g}: `{m['version']}`: **{m['status']}**", "",
              f"Created {m['created_at']} · code {m['code_sha']} · data {m['data_hash'][:16]} · calibrator {m.get('calibrator')} · qhat {f(m.get('qhat'))}", "",
              "| variant | n_oos | brier skill | logloss (model / base) | ECE | AUC | taken | mean R taken | total R taken | DSR |",
              "|---|---|---|---|---|---|---|---|---|---|"]
        for v, s in (mt.get("variants") or {}).items():
            L.append(f"| {v} | {s['n_oos']} | {f(s['brier_skill'])} | {f(s['logloss'])} / {f(s['logloss_baseline'])} | {f(s['ece'])} | {f(s['auc'])} | "
                     f"{s['n_taken']} | {f(s['mean_r_taken'])} | {f(s['total_r_taken'], 2)} | {f((s.get('dsr') or {}).get('dsr'))} |")
        ta = mt.get("take_all") or {}
        L += [f"| take_all (no filter) | {ta.get('n')} | | | | | {ta.get('n')} | {f(ta.get('mean_r'))} | {f(ta.get('total_r'), 2)} | |", "",
              f"PBO (CSCV, 5 strategies): {f((mt.get('pbo') or {}).get('pbo'))}", "",
              "| instrument | n_oos | base rate | brier skill | AUC | taken | mean R taken | mean R all (take-all) |", "|---|---|---|---|---|---|---|---|"]
        for i, d in sorted((mt.get("per_instrument") or {}).items()):
            s = d["hgb_conformal"]
            L.append(f"| {i} | {s['n_oos']} | {f(s['base_rate_oos'])} | {f(s['brier_skill'])} | {f(s['auc'])} | {s['n_taken']} | {f(s['mean_r_taken'])} | {f(s['mean_r_all'])} |")
        L += ["", "Gates: " + "; ".join(f"{x['gate']} {'PASS' if x['passed'] else 'FAIL'}" for x in m["gates"]), ""]
    L += ["See [README.md](README.md) for method and [limitations.md](limitations.md)."]
    open(out, "w").write("\n".join(L) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(*sys.argv[1:]))
